mapper.select:
        select  distinct U_ID from  SYS_Position p
        left  join   SYS_Position_User pu on p.P_ID= pu.P_ID  where  pu.PU_ID is not null

         ${uIdSql}

select U_ID as uId,SYS_Position.P_ID as pId,D_ID as dId    from   SYS_Position_User
left join  SYS_Position on SYS_Position_User.P_ID=SYS_Position.P_ID
left join  Pre_Project on P_Competent_Department= D_ID   where     Pre_Project.P_ID=#{pId};
